# Debug symbols aren't available on the symbol server for this build.
# Let's use the stripped binary's .dynsym table more carefully.
# Actually, addr2line was already giving us function names from the PLT/dynsym.
# Let me use a more sophisticated approach - get all symbols and find the closest preceding one

readelf -W --dyn-syms /tmp/libmonosgen-2.0.so | awk '$4 == "FUNC" && $7 != "UND"' | awk '{print $2, $8}' | sort > /tmp/mono_sorted.txt

for addr in 0x222098 0x2241ac 0x1abc80 0x1abd14 0x16dfa4 0x16db6c 0x16de04; do
  match=$(awk -v target="$addr" '
    BEGIN { target_dec = strtonum(target) }
    { 
      sym_addr = strtonum("0x" $1)
      if (sym_addr <= target_dec) { 
        best_addr = sym_addr; best_name = $2
      }
    }
    END { 
      if (best_name != "") {
        offset = target_dec - best_addr
        printf "%s+0x%x\n", best_name, offset
      } else print "??"
    }
  ' /tmp/mono_sorted.txt)
  echo "  $addr: $match"
done

