arguments.command:
# Parse .eh_frame to find FDEs (Frame Descriptor Entries) that cover our addresses
# Each FDE defines a function range (start, length)
readelf -W --debug-dump=frames /tmp/libmonosgen-2.0.so 2>/dev/null | grep -B1 "pc=" | grep "pc=" | awk '{
  for (i=1; i<=NF; i++) {
    if ($i ~ /^pc=/) {
      split($i, a, "=")
      split(a[2], b, "\\.\\.")
      gsub(/\.\./, " ", a[2])
      print a[2]
    }
  }
}' | head -5

# Let's extract all FDE ranges and find which ones contain our addresses
readelf -W --debug-dump=frames /tmp/libmonosgen-2.0.so 2>/dev/null | grep "pc=" | sed 's/.*pc=\([0-9a-f]*\)\.\.\([0-9a-f]*\).*/\1 \2/' > /tmp/fde_ranges.txt
wc -l /tmp/fde_ranges.txt

echo "=== Functions containing our addresses ==="
for addr in 222098 2241ac 1abc80 1abd14 16dfa4 16db6c 16de04; do
  match=$(awk -v target="0x$addr" '
    BEGIN { t = strtonum(target) }
    { 
      start = strtonum("0x" $1)
      end = strtonum("0x" $2)
      if (start <= t && t < end) {
        printf "0x%s..0x%s (size 0x%x)\n", $1, $2, end-start
        exit
      }
    }
  ' /tmp/fde_ranges.txt)
  echo "  0x$addr -> $match"
done

