      sym_addr = strtonum($1)
      dist = t - sym_addr
      if (dist >= 0 && dist < best_dist) {
        best_dist = dist; best_name = $3; best_addr = $1
      }
    }
    END { printf "%s (at 0x%s, offset +0x%x)\n", best_name, best_addr, best_dist }
  ' /tmp/all_funcs.txt)
  echo "  func at $start -> nearest export: $nearest"
done", "description": "Correlate function starts with known symbols"}

