arguments.command:
python3 << 'EOF'
# Let's resolve the call targets to known symbol names
# First build a map of address -> symbol from the sorted symbols

syms = {}
with open('/tmp/all_funcs.txt') as f:
    for line in f:
        parts = line.strip().split()
        if len(parts) >= 3:
            addr = int(parts[0], 16)
            name = parts[2]
            syms[addr] = name

# Find exact matches for call targets
call_targets = {
    "#01 (0x221fdc)": [0x1d5678, 0x26623c, 0x1d50c0, 0x261af0],
    "#02 (0x22416c)": [0x2ecec0, 0x221fdc],
    "#03 (0x1abb3c)": [0x2387b4, 0x2ee240, 0x1d5790],
    "#04 (0x1abd10)": [0x141358, 0x1997f8, 0xca610],
    "#05-07 (0x16d400)": [0xc3544, 0x2ecb40, 0x2ed050, 0x241404, 0x16f72c, 0x108ddc, 0x2ec570],
}

for frame, targets in call_targets.items():
    print(f"\nFrame {frame} calls:")
    for t in targets:
        if t in syms:
            print(f"  0x{t:x} = {syms[t]}")
        else:
            # Find nearest
            best = None
            for sa in sorted(syms.keys()):
                if sa <= t:
                    best = (sa, syms[sa])
            if best:
                print(f"  0x{t:x} ~ {best[1]}+0x{t-best[0]:x}")
            else:
                print(f"  0x{t:x} = ??")
EOF

